import{_ as e,o as a,c as d,a3 as c}from"./chunks/framework.DdpBa4_E.js";const g=JSON.parse('{"title":"通用篇 - 使用 Command","description":"","frontmatter":{},"headers":[],"relativePath":"books/chrome-devtools/04-通用篇-使用-Command.md","filePath":"books/chrome-devtools/04-通用篇-使用-Command.md","lastUpdated":1794316978000}'),t={name:"books/chrome-devtools/04-通用篇-使用-Command.md"};function s(l,o,i,m,r,p){return a(),d("div",null,[...o[0]||(o[0]=[c('<h1 id="通用篇-使用-command" tabindex="-1">通用篇 - 使用 Command <a class="header-anchor" href="#通用篇-使用-command" aria-label="Permalink to &quot;通用篇 - 使用 Command&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>我们直接可以直接看到的 <code>DevTools</code> 的功能，其实只是有限的一部分，怎么去探索更多的功能呢？</p><p><code>Command</code> 菜单可以帮助我们快速找到那些被隐藏起来的功能，这也是它本身必不可少的原因。</p><p>如果你使用过 <code>WebStorm</code> 中的 <code>Find Action</code> (查找动作) 或者 <code>Visual Studio Code</code> 中的 <code>Command Palette</code> 的话，那么在 <code>DevTools</code> 中的 <code>Command</code> 菜单也与之类似：</p><ul><li>在 <code>Chrome</code> 的调试打开的情况下 按下 [ <code>Ctrl]</code> + <code>[Shift]</code> + <code>[P]</code> (Mac： <code>[⌘]</code> + <code>[Shift]</code>+ <code>[P]</code> )</li><li>或者使用 <code>DevTools</code> 的 <code>dropdown</code> 按钮下的这个选项:</li></ul><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/11/1679a2adf8945253~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p>下图中，我整理了可供选择的命令列表，归为几个部分：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/11/1679a2e13926d71b~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><blockquote><p>上面这张图同时也证明了 <code>DevTools</code> 有多么强力!</p></blockquote><h2 id="_1-截屏的新姿势" tabindex="-1">1.截屏的新姿势 <a class="header-anchor" href="#_1-截屏的新姿势" aria-label="Permalink to &quot;1.截屏的新姿势&quot;">​</a></h2><p>当你只想对一个特别的 <code>DOM</code> 节点进行截图时，你可能需要使用其他工具弄半天，但现在你直接选中那个节点，打开 <code>Command</code> 菜单并且使用 <strong>节点截图</strong> 的就可以了。</p><p>不只是这样，你同样可以用这种方式 <strong>全屏截图</strong> - 通过 <code>Capture full size screenshot</code> 命令。请注意，这里说的是全屏，并不是嵌入页面的一部分。一般来说这可是得使用浏览器插件才能做到的事情！</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/11/1679a37dbce34984~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><blockquote><p>注：<strong><code>节点截图有时会失效</code></strong>，全屏截图暂时没有遇到问题，建议大家使用后者。</p></blockquote><h2 id="_2-快速切换面板" tabindex="-1">2.快速切换面板 <a class="header-anchor" href="#_2-快速切换面板" aria-label="Permalink to &quot;2.快速切换面板&quot;">​</a></h2><p><code>DevTools</code> 使用双面板布局，形式一般是：<code>元素面板</code> + <code>资源面板</code> ，它根据屏幕可用的部分，经常将不同面板横向或者纵向的排列，以适合阅读的方式展示出来。但有时候我们并不喜欢默认的布局。</p><p>你是否想过要重置 <code>DevTools</code> 呢？将 <code>样式面板</code> 从 <code>html预览</code> 的底部移动到右边或者周围其他的位置呢？是的，这就是下面要介绍的 😉</p><p>打开 <code>Commands</code> 菜单并且输入 <code>layout</code> ，你会看到 <code>2</code> 到 <code>3</code> 个可供选择的项(这里不再显示你已经激活的选项)：</p><ul><li>使用横向面板布局</li><li>使用纵向面板布局</li><li>使用自动面板布局</li></ul><p>试试看：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/11/1679a4aa44c58106~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_3-快速切换主题" tabindex="-1">3.快速切换主题 <a class="header-anchor" href="#_3-快速切换主题" aria-label="Permalink to &quot;3.快速切换主题&quot;">​</a></h2><p>经常在电脑前一坐就是一天，所以我不能忍受一直看着白闪闪的屏幕。而且突然出现的强光也让人讨厌：我们一直都在黑暗的空间中工作，突然太阳出来了，照在你的 <code>DevTools</code> 上，导致你什么都看不到！</p><p>这个时候 <code>主题</code> 就派上了用场了：在 <code>Commands</code> 菜单中寻找与 <code>theme</code> 相关的选项，实现 <code>明亮</code> &amp; <code>暗黑</code> 两种主题之间的切换：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/11/1679a56481366d25~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p>',26)])])}const h=e(t,[["render",s]]);export{g as __pageData,h as default};
